import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_hw_forward(torch::Tensor x,
                                 torch::Tensor weight,
                                 c10::optional<torch::Tensor> bias,
                                 int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled kernel for a Conv3d whose kernel is (K,K,1):
// treated as an independent 2D (K x K) convolution applied per-depth-slice,
// with general stride/padding/dilation/groups applied uniformly to H, W, and D
// (kernel size along D is 1, so D acts purely as a "select-with-stride/padding" dim).
template <int TILE_H, int TILE_W>
__global__ void conv2d_depthslice_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bs,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Hout, int Wout, int Dout,
    int K, int stride, int padding, int dilation, int groups,
    int TileInH, int TileInW)
{
  extern __shared__ float smem[];

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;

  float* sIn_ptr = smem;
  float* sW_ptr  = smem + (size_t)Cin * TileInH * TileInW;

  auto sIn = make_tensor(make_smem_ptr(sIn_ptr),
                          make_shape(Cin, TileInH, TileInW),
                          make_stride(TileInH * TileInW, TileInW, 1));
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(Cout, Cin_per_group, K, K),
                         make_stride(Cin_per_group * K * K, K * K, K, 1));

  const int nd = blockIdx.z;
  const int n  = nd / Dout;
  const int od = nd % Dout;
  const int id = od * stride - padding; // depth kernel size = 1

  const int tile_h0 = blockIdx.y * TILE_H;
  const int tile_w0 = blockIdx.x * TILE_W;

  const int blockThreads = TILE_H * TILE_W;
  const int tx = threadIdx.x % TILE_W;
  const int ty = threadIdx.x / TILE_W;
  const int oh = tile_h0 + ty;
  const int ow = tile_w0 + tx;

  const bool depth_valid = (id >= 0 && id < D);

  // Strides for X: (N, Cin, H, Win, D) contiguous, D fastest
  const int64_t sXd = 1;
  const int64_t sXw = D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXc = (int64_t)H * sXh;
  const int64_t sXn = (int64_t)Cin * sXc;

  // Strides for Y: (N, Cout, Hout, Wout, Dout) contiguous
  const int64_t sYd = 1;
  const int64_t sYw = Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYc = (int64_t)Hout * sYh;
  const int64_t sYn = (int64_t)Cout * sYc;

  const int base_ih = tile_h0 * stride - padding;
  const int base_iw = tile_w0 * stride - padding;

  const int total_load = Cin * TileInH * TileInW;

  if (depth_valid) {
    const float* Xbase = X + (int64_t)n * sXn + (int64_t)id * sXd;
    for (int idx = threadIdx.x; idx < total_load; idx += blockThreads) {
      int c   = idx / (TileInH * TileInW);
      int rem = idx % (TileInH * TileInW);
      int r   = rem / TileInW;
      int cc  = rem % TileInW;
      int ih  = base_ih + r;
      int iw  = base_iw + cc;
      float v = 0.0f;
      if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
        v = Xbase[(int64_t)c * sXc + (int64_t)ih * sXh + (int64_t)iw * sXw];
      }
      sIn(c, r, cc) = v;
    }
  } else {
    for (int idx = threadIdx.x; idx < total_load; idx += blockThreads) {
      int c   = idx / (TileInH * TileInW);
      int rem = idx % (TileInH * TileInW);
      int r   = rem / TileInW;
      int cc  = rem % TileInW;
      sIn(c, r, cc) = 0.0f;
    }
  }

  const int total_w = Cout * Cin_per_group * K * K;
  for (int idx = threadIdx.x; idx < total_w; idx += blockThreads) {
    sW_ptr[idx] = Wt[idx];
  }

  __syncthreads();

  if (oh < Hout && ow < Wout) {
    float* Ybase = Y + (int64_t)n * sYn + (int64_t)od * sYd;
    for (int co = 0; co < Cout; ++co) {
      const int g = co / Cout_per_group;
      const int ci_start = g * Cin_per_group;
      float acc = (Bs != nullptr) ? Bs[co] : 0.0f;

      for (int cir = 0; cir < Cin_per_group; ++cir) {
        const int ci = ci_start + cir;
        for (int kh = 0; kh < K; ++kh) {
          const int lr = ty * stride + kh * dilation;
          for (int kw = 0; kw < K; ++kw) {
            const int lc = tx * stride + kw * dilation;
            acc += sIn(ci, lr, lc) * sW(co, cir, kh, kw);
          }
        }
      }
      Ybase[(int64_t)co * sYc + (int64_t)oh * sYh + (int64_t)ow * sYw] = acc;
    }
  }
}

torch::Tensor conv3d_hw_forward(torch::Tensor x,
                                 torch::Tensor weight,
                                 c10::optional<torch::Tensor> bias,
                                 int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be 5D (N,C,H,W,D)");
  TORCH_CHECK(weight.dim() == 5, "weight must be 5D (Cout,Cin/groups,Kh,Kw,Kd)");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t H   = x_c.size(2);
  int64_t Win = x_c.size(3);
  int64_t D   = x_c.size(4);

  int64_t Cout          = w_c.size(0);
  int64_t Cin_per_group = w_c.size(1);
  int64_t K             = w_c.size(2);
  TORCH_CHECK(w_c.size(3) == K, "kernel must be square (Kh==Kw)");
  TORCH_CHECK(w_c.size(4) == 1, "kernel depth must be 1");
  TORCH_CHECK(Cin % groups == 0 && Cout % groups == 0, "channels must be divisible by groups");
  TORCH_CHECK(Cin_per_group == Cin / groups, "weight in-channel mismatch with groups");

  int64_t Hout = (H   + 2*padding - dilation*(K-1) - 1) / stride + 1;
  int64_t Wout = (Win + 2*padding - dilation*(K-1) - 1) / stride + 1;
  int64_t Dout = (D   + 2*padding - 0                - 1) / stride + 1; // kernel depth = 1

  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "invalid computed output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias shape mismatch");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

  constexpr int TILE_H = 16;
  constexpr int TILE_W = 16;

  int TileInH = (TILE_H - 1) * stride + (int)((K - 1) * dilation) + 1;
  int TileInW = (TILE_W - 1) * stride + (int)((K - 1) * dilation) + 1;

  dim3 block((unsigned)(TILE_H * TILE_W));
  dim3 grid((unsigned)((Wout + TILE_W - 1) / TILE_W),
            (unsigned)((Hout + TILE_H - 1) / TILE_H),
            (unsigned)(N * Dout));

  size_t shmem_bytes = ((size_t)Cin * TileInH * TileInW +
                         (size_t)Cout * Cin_per_group * K * K) * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_depthslice_kernel<TILE_H, TILE_W><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win, (int)D,
      (int)Cout, (int)Hout, (int)Wout, (int)Dout,
      (int)K, stride, padding, dilation, groups,
      TileInH, TileInW
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_depthslice_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_hw_kernel1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_hw_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Conv3d with kernel (K,K,1) implemented as a cooperative tiled 2D convolution
    per depth-slice using a custom CUDA/CuTe kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        # Reuse nn.Conv3d purely as a parameter holder / initializer to match
        # PyTorch's exact initialization semantics.
        self.conv3d = nn.Conv3d(in_channels, out_channels,
                                 (kernel_size, kernel_size, 1),
                                 stride=stride, padding=padding, dilation=dilation,
                                 groups=groups, bias=bias)
        self._ext = conv3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.conv3d.weight
        b = self.conv3d.bias
        stride = self.conv3d.stride[0]
        padding = self.conv3d.padding[0]
        dilation = self.conv3d.dilation[0]
        groups = self.conv3d.groups
        return self._ext.conv3d_hw_forward(
            x.contiguous(), w.contiguous(),
            b if b is not None else None,
            int(stride), int(padding), int(dilation), int(groups)
        )

